      "claim": "Strips 'www.' only when the subdomain label has at least 2 characters, breaking valid hostnames like 'www.a.com'",
      "file": "index.js",
      "line": 208,
      "severity": "major",
      "witnessCode": "import { strict } from 'node:assert';\nimport x from '../index.js';\n\nconst { normalizeUrl } = x;\n\nconst input = 'http://www.a.com/path';\nconst options = { stripWWW: true };\n\nconst expected = 'http://a.com/path';\n\nstrict.deepStrictEqual(\\n  normalizeUrl(input, options),\\n  expected,\\n  'normalizeUrl should strip www. for single‑character SLD'\\n);"
    }
  ]
}
